/bin/zsh -lc "cat > tb_check.sv <<'EOF'
module tb;
  reg clk=0, rst_n=0, a=0;
  wire match;
  integer errors=0;
  reg [8:0] window;
  TopModule dut(.clk(clk),.rst_n(rst_n),.a(a),.match(match));
  always #5 clk=~clk;

  task send(input bit b);
    reg [8:0] next_window;
    reg expected;
    begin
      a=b;
      next_window = {window[7:0], b};
      expected = (next_window[8:6] == 3'b011) && (next_window[2:0] == 3'b110);
      @(posedge clk);
      #1;
      if (match "'!== expected) begin
        $display("ERR t=%0t next=%09b expected=%0b got=%0b", $time, next_window, expected, match);
        errors = errors + 1;
      end
      window = next_window;
    end
  endtask

  initial begin
    window = 0;
    repeat(2) @(posedge clk);
    rst_n=1;
    send(0); send(1); send(1); send(0); send(0); send(0); send(1); send(1); send(0);
    send(0); send(1); send(1); send(1); send(1); send(1); send(1); send(1); send(0);
    send(0); send(1); send(1); send(1); send(0); send(1); send(1); send(1); send(0);
    if (errors == 0) $display("PASS");
    else $display("FAIL errors=%0d", errors);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv_check TopModule.sv tb_check.sv && vvp simv_check'

